import{_ as n,o as a,c as i,a4 as l}from"./chunks/framework.B-wJupoK.js";const p="/assets/image-20240718201721853.D8pTsUhQ.png",e="/assets/image-20240718204400711.C-3ySCXd.png",h="/assets/image-20240718215338082.Bgwrse9B.png",t="/assets/image-20240718215929872.CQpBlp3p.png",k="/assets/image-20240718220523209.pKIhitlS.png",r="/assets/image-20240715182615579.Db8qdTxN.png",E="/assets/image-20240718222428155.CB_7QGJu.png",F=JSON.parse('{"title":"HarmonyOS Next V2 @Local和@Param","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/HarmonyOS Next V2 状态管理/HarmonyOS Next V2 @Local和@Param/@Local和@Param.md","filePath":"鸿蒙开发技巧/HarmonyOS Next V2 状态管理/HarmonyOS Next V2 @Local和@Param/@Local和@Param.md","lastUpdated":1730788610000,"__rawMarkdown":"# HarmonyOS Next V2 @Local和@Param\\n\\n## @Local 背景\\n\\n**@Local**  是**harmony**应用开发中的v2版本中 对标**@State**的状态管理修饰器，它解决了 @State 对状态变量更改的检测混乱的问题：\\n\\n1. **@State** 修饰的状态变量 可以是组件内部自己定义的\\n2. **@State** 修饰的状态 也可以由外部父组件传递\\n\\n这样就导致了状态数据来源不唯一，在大型项目中会引发难易检测和维护状态的问题。如以下代码：\\n\\n```typescript\\n@Entry\\n@Component\\nstruct Index {\\n  @State num: number = 100\\n\\n  build() {\\n    Column() {\\n      Text(\\"父组件的数据 \\" + this.num)\\n\\n      Son({ num: this.num })\\n      Son()\\n    }\\n    .height(\'100%\')\\n    .width(\'100%\')\\n  }\\n}\\n\\n@Component\\nstruct Son {\\n  @State num: number = 0\\n\\n  build() {\\n    Column() {\\n      Button(`子组件 ${this.num}`)\\n        .onClick(() => {\\n          this.num++\\n        })\\n    }\\n  }\\n}\\n```\\n\\n![image-20240718201721853](readme.assets/image-20240718201721853.png)\\n\\n## @Local 基本使用\\n\\n**@Local**的出现就是为了解决这一类问题\\n\\n1. **@Local** 只能用在 **@Componentv2** 修饰的组件上\\n2. 被**@Local**装饰的变量无法从外部初始化(无法由父组件传递进来)，因此必须在组件内部进行初始化\\n\\n我们对上面代码稍作修改\\n\\n```typescript\\n@Entry\\n@Component\\nstruct Index {\\n  @State num: number = 100\\n\\n  build() {\\n    Column() {\\n      Text(\\"父组件的数据 \\" + this.num)\\n\\n      Son({ num: this.num }) // 这里就报错啦\\n\\n      Son()\\n    }\\n    .height(\'100%\')\\n    .width(\'100%\')\\n  }\\n}\\n\\n@ComponentV2 // 此处调整为 @ComponentV2\\nstruct Son {\\n\\n  // 此处调整为 @Local\\n  @Local num: number = 0\\n\\n  build() {\\n    Column() {\\n      Button(`子组件 ${this.num}`)\\n        .onClick(() => {\\n          this.num++\\n        })\\n    }\\n  }\\n}\\n```\\n\\n\\n\\n\\n\\n![image-20240718204400711](readme.assets/image-20240718204400711.png)\\n\\n## @Local与@State对比\\n\\n|                | @State                                           | @Local                                     |\\n| -------------- | ------------------------------------------------ | ------------------------------------------ |\\n| 参数           | 无。                                             | 无。                                       |\\n| 从父组件初始化 | 可选。                                           | 不允许外部初始化。                         |\\n| 观察能力       | 能观测变量本身以及一层的成员属性，无法深度观测。 | 能观测变量本身，深度观测依赖@Trace装饰器。 |\\n| 数据传递       | 可以作为数据源和子组件中状态变量同步。           | 可以作为数据源和子组件中状态变量同步。     |\\n\\n## @Local  特别注意\\n\\n- @Local支持观测number、boolean、string、Object、class等基本类型以及Array、Set、Map、Date等内嵌类型。\\n- @Local的观测能力仅限于被装饰的**变量本身**。当装饰简单类型时，能够观测到对变量的赋值；当装饰对象类型时，仅能观测到对对象整体的赋值；当装饰数组类型时，能观测到数组整体以及数组元素项的变化；当装饰Array、Set、Map、Date等内嵌类型时，可以观测到通过API调用带来的变化。\\n\\n## @Params \\n\\n**@Params**主要表示 子组件 接收父组件传递的数据。可以和 **@Local** 搭配一起使用\\n\\n## @Params 背景\\n\\n在V1版本的状态管理修饰符中，可以用来处理 父子传参的技术有：\\n\\n1. 普通属性，不需要特别的修饰符 ， 不具备单向同步\\n2. @Prop 单向同步，不能监听深层次属性的改变，也不能做到双向同步\\n3. @Link 可以做到双向同步，但是不能监听深层次属性的改变，而且不能直接用在 列表渲染技术 - ForEach 中\\n4. @ObjectLink 可以做到双向同步，但是必须和  @Observed 搭配使用 ，而且只能用在自定义组件上\\n\\n\\n\\n### 1. 普通属性\\n\\n普通属性，不需要特别的修饰符 ， 不具备单向同步\\n\\n```typescript\\n@Entry\\n@Component\\nstruct Index {\\n  @State num: number = 100\\n\\n  build() {\\n    Column() {\\n      // 父组件传递过去的数据\\n      Son({ num: this.num })\\n        .onClick(() => {\\n          this.num++\\n          console.log(\\"\\", this.num)\\n        })\\n    }\\n    .height(\'100%\')\\n    .width(\'100%\')\\n  }\\n}\\n\\n@Component\\nstruct Son {\\n  num: number = 0\\n\\n  build() {\\n    Column() {\\n      Button(`子组件 ${this.num}`)\\n    }\\n  }\\n}\\n```\\n\\n![image-20240718215338082](readme.assets/image-20240718215338082.png)\\n\\n### 2. @Prop 单向同步\\n\\n@Prop 单向同步\\n\\n1. 不能监听深层次属性的改变\\n2. 也不能做到**双向同步**\\n\\n在上面代码基础上 加入**@Prop**，可以检测到基本类型数据的更新\\n\\n```\\n@Component\\nstruct Son {\\n  @Prop num: number = 0\\n```\\n\\n但是无法检测深层次属性的改变,如\\n\\n```typescript\\nclass Animal {\\n  dog: Dog = {\\n    age: 100\\n  }\\n}\\n\\nclass Dog {\\n  age: number = 100\\n}\\n\\n@Entry\\n@Component\\nstruct Index {\\n  @State\\n  animal: Animal = new Animal()\\n\\n  build() {\\n    Column() {\\n      // 父组件传递过去的数据\\n      Son({ dog: this.animal.dog })\\n        .onClick(() => {\\n          this.animal.dog.age++\\n          console.log(\\"\\", this.animal.dog.age)\\n        })\\n    }\\n    .height(\'100%\')\\n    .width(\'100%\')\\n  }\\n}\\n\\n@Component\\nstruct Son {\\n  @Prop dog: Dog\\n\\n  build() {\\n    Column() {\\n      Button(`子组件 ${this.dog.age}`)\\n    }\\n  }\\n}\\n```\\n\\n\\n\\n![image-20240718215929872](readme.assets/image-20240718215929872.png)\\n\\n### 3. @Link 双向同步\\n\\n> @Link 用法和@Prop基本一致\\n\\n 可以做到双向同步，但是\\n\\n1. 不能监听深层次属性的改变\\n\\n2. 而且不能直接用在 列表渲染技术 - **ForEach** 中  *以下代码演示这个效果*\\n\\n   ```typescript\\n   class Dog {\\n     age: number = 100\\n   }\\n   \\n   @Entry\\n   @Component\\n   struct Index {\\n     @State\\n     dogList: Dog [] = [new Dog(), new Dog(), new Dog(), new Dog()]\\n   \\n     build() {\\n       Column() {\\n         ForEach(this.dogList, (item: Dog) => {\\n           // 此处会报错  Assigning the attribute \'item\' to the \'@Link\' decorated attribute \'dog\' is not allowed. <ArkTSCheck>\\n           Son({ dog: item })\\n             .onClick(() => {\\n               item.age++\\n               console.log(\\"\\", item.age)\\n             })\\n         })\\n   \\n       }\\n       .height(\'100%\')\\n       .width(\'100%\')\\n     }\\n   }\\n   \\n   @Component\\n   struct Son {\\n     @Link dog: Dog\\n   \\n     build() {\\n       Column() {\\n         Button(`子组件 ${this.dog.age}`)\\n       }\\n     }\\n   }\\n   ```\\n\\n   ---\\n\\n   ![image-20240718220523209](readme.assets/image-20240718220523209.png)\\n\\n### 4. @ObjectLink \\n\\n@ObjectLink 可以做到双向同步，但是必须和  @Observed 搭配使用 ，而且只能用在**自定义组件**上\\n\\n![image-20240715182615579](readme.assets/image-20240715182615579.png)\\n\\n\\n\\n### 小结\\n\\n可以看到，如果都是使用 v1版本的这一套 父子传参的技术，是十分复杂难易直接上手使用的。\\n\\n\\n\\n## @Params 介绍\\n\\nParam表示组件从外部传入的状态，使得父子组件之间的数据能够进行同步：\\n\\n- @Param装饰的变量支持本地初始化，但是不允许在组件内部直接修改变量本身。\\n  - 如果不本地初始化，那么必须加入 **@Require**\\n- @Param 可以做到单向同步\\n- @Param 可以检测深层次属性的修改，但是该修改在数据源上必须是整体对象的更新\\n- @Params 如果也想要深度监听单个属性的修改，那么需要使用  **@ObservedV2** 和 **@Trace**\\n\\n\\n\\n以下代码主要演示：**@Param 可以检测深层次属性的修改，但是该修改在数据源上必须是整体对象的更新**\\n\\n```typescript\\nclass Person {\\n  age: number = 100\\n}\\n@Entry\\n@ComponentV2\\nstruct Index {\\n  @Local\\n  person: Person = new Person()\\n  build() {\\n    Column() {\\n      Son({ age: this.person.age })\\n        .onClick(() => {\\n          this.person.age++\\n          console.log(\\"\\", this.person.age)\\n          if (this.person.age === 105) {\\n            const p = new Person()\\n            p.age = 200\\n            // 整体更新，子组件可以感知到\\n            this.person = p\\n          }\\n        })\\n    }\\n    .height(\'100%\')\\n    .width(\'100%\')\\n  }\\n}\\n\\n@ComponentV2\\nstruct Son {\\n  // 要么设置 @Require 表示父组件必须传递数据\\n  // 要么设置 默认值\\n  @Require @Param age: number\\n  build() {\\n    Column() {\\n      Button(`子组件 ${this.age}`)\\n    }\\n  }\\n}\\n```\\n\\n![image-20240718222428155](readme.assets/image-20240718222428155.png)\\n\\n\\n\\n\\n\\n## 总结\\n\\n1. @Local 可以看成是 @State的替代 ，单独表示组件内部的状态\\n2. @Params 可以看成 @Prop @Link @ObjectLink的替代，更加严谨\\n3. @Local 和 @Params 搭配一起使用，都只能用在 @Componentv2 修饰的自定义组件上\\n\\n"}'),d={name:"鸿蒙开发技巧/HarmonyOS Next V2 状态管理/HarmonyOS Next V2 @Local和@Param/@Local和@Param.md"};function g(c,s,b,o,y,m){return a(),i("div",null,[...s[0]||(s[0]=[l("",51)])])}const C=n(d,[["render",g]]);export{F as __pageData,C as default};
